using I=mpz_class;using Q=mpq_class;constexpr int D=7;using V=std::array<I,D>;using B=std::array<V,D>;using QV=std::array<Q,D>;using Clock=std::chrono::steady_clock;
void need(bool x,const char*s){if(!x)throw std::runtime_error(s);}I fd(I x,I y){need(y!=0,"division");if(y<0){x=-x;y=-y;}I q=x/y,r=x%y;return q-(r<0?1:0);}I cd(I x,I y){return -fd(-x,y);}I mod(I x,const I&p){x%=p;if(x<0)x+=p;return x;}I center(I x,const I&p){x=mod(x,p);if(2*x>p)x-=p;return x;}I nearest(const Q&q){return fd(I(2*q.get_num()+q.get_den()),I(2*q.get_den()));}
struct GS{std::array<QV,D>s{};std::array<QV,D>mu{};QV norm{};};GS gram(const B&b){GS g;for(int i=0;i<D;i++){for(int t=0;t<D;t++)g.s[i][t]=Q(b[i][t]);for(int j=0;j<i;j++){need(g.norm[j]>0,"rank");Q dot=0;for(int t=0;t<D;t++)dot+=Q(b[i][t])*g.s[j][t];g.mu[i][j]=dot/g.norm[j];for(int t=0;t<D;t++)g.s[i][t]-=g.mu[i][j]*g.s[j][t];}for(int t=0;t<D;t++)g.norm[i]+=g.s[i][t]*g.s[i][t];}return g;}
bool lll(B&b,unsigned&steps,Clock::time_point started){int k=1;GS g=gram(b);while(k<D&&steps<1024){if(std::chrono::duration<double>(Clock::now()-started).count()>65)return false;steps++;for(int j=k-1;j>=0;j--){I z=nearest(g.mu[k][j]);if(z!=0){for(int t=0;t<D;t++)b[k][t]-=z*b[j][t];g=gram(b);}}if(g.norm[k]>=(Q(3,4)-g.mu[k][k-1]*g.mu[k][k-1])*g.norm[k-1])k++;else{std::swap(b[k],b[k-1]);g=gram(b);k=std::max(k-1,1);}}return k==D;}
void arr(std::ostream&o,const V&v){o<<'[';for(int i=0;i<D;i++){if(i)o<<',';o<<'"'<<v[i]<<'"';}o<<']';}
I qe(const I&a,const I&b,const I&c,const I&s){return a*s*s+b*s+c;}
std::pair<I,I> quadratic(const I&a,const I&b,const I&c,const I&A){I low=qe(a,b,c,0),high=low;auto take=[&](I x){if(x<0||x>A)return;I y=qe(a,b,c,x);if(y<low)low=y;if(y>high)high=y;};take(A);if(a!=0){I k=fd(I(-b),I(2*a));take(k);take(I(k+1));}return{low,high};}
std::pair<I,I> curved(const V&v,const I&cc,const I&M,const I&u){I a=v[0],b=-2*v[0]*u*u-v[1]*u+v[3],c=v[0]*u*u*u*u+v[1]*u*u*u+v[2]*u*u+v[4]*u+cc;auto r=quadratic(a,b,c,I(3*M));for(auto q:{I(-v[5]*3*M*M),I(-v[6]*M*M*M)}){if(q<0)r.first+=q;else r.second+=q;}return r;}
void nativecontrols(){unsigned long count=0;for(long a=-3;a<=3;a++)for(long b=-3;b<=3;b++)for(long c=-3;c<=3;c++)for(long A=0;A<=12;A++){auto r=quadratic(I(a),I(b),I(c),I(A));long lo=c,hi=c;for(long s=0;s<=A;s++){long z=a*s*s+b*s+c;lo=std::min(lo,z);hi=std::max(hi,z);}need(r.first==lo&&r.second==hi,"independent machine quadratic extrema");count++;}std::cout<<"{\"quadratic_extrema_cases\":"<<count<<"}\n";}

I determinant(B a){I previous=1;int sign=1;for(int k=0;k<D-1;k++){int pivot=k;while(pivot<D&&a[pivot][k]==0)pivot++;if(pivot==D)return 0;if(pivot!=k){std::swap(a[pivot],a[k]);sign=-sign;}I v=a[k][k];for(int i=k+1;i<D;i++)for(int j=k+1;j<D;j++){I n=a[i][j]*v-a[i][k]*a[k][j];need(n%previous==0,"exact Bareiss division");a[i][j]=n/previous;}for(int i=k+1;i<D;i++)a[i][k]=0;previous=v;}return sign*a[D-1][D-1];}
bool validbasis(const B&basis,const I&p,const std::array<I,6>&a,const std::array<I,6>&b){for(const auto&row:basis)for(int j=0;j<5;j++)if(mod(I(row[j]-row[5]*a[j]-row[6]*b[j]),p)!=0)return false;I det=determinant(basis);if(det<0)det=-det;I target;mpz_pow_ui(target.get_mpz_t(),p.get_mpz_t(),5);return det==target;}
B original(const I&p,const std::array<I,6>&a,const std::array<I,6>&b){B basis{};for(int j=0;j<5;j++){basis[j][j]=p;basis[5][j]=center(a[j],p);basis[6][j]=center(b[j],p);}basis[5][5]=1;basis[6][6]=1;return basis;}
void basiscontrols(){unsigned n=0;for(long pp:{3L,5L,7L}){I p=pp;std::array<I,6>a{1,2,3,4,5,6},b{6,5,4,3,2,1};B base=original(p,a,b);need(validbasis(base,p,a,b),"original basis");for(int rep=0;rep<12;rep++){B z=base;std::swap(z[0],z[1]);for(int j=0;j<D;j++)z[2][j]+=I(rep-6)*z[6][j];need(validbasis(z,p,a,b),"unimodular invariance");V w;for(int j=0;j<D;j++)w[j]=1+((j+rep)%5);B scaled=z;for(auto&row:scaled)for(int j=0;j<D;j++)row[j]*=w[j];unsigned steps=0;lll(scaled,steps,Clock::now());for(auto&row:scaled)for(int j=0;j<D;j++){need(row[j]%w[j]==0,"test unscale");row[j]/=w[j];}need(validbasis(scaled,p,a,b),"metric repair lattice");B corrupt=scaled;for(auto&v:corrupt[0])v*=2;need(!validbasis(corrupt,p,a,b),"corrupt index rejection");n++;}}std::cout<<"{\"basis_metric_controls\":"<<n<<"}\n";}
struct Input{std::string id,key;I p,M,H;std::array<I,6>a,b;};
std::string fingerprint(const Input&x){std::ostringstream o;o<<x.p<<' '<<x.M;for(const auto&v:x.a)o<<' '<<v;for(const auto&v:x.b)o<<' '<<v;return o.str();}
struct Cache{std::string fingerprint;B basis;};
struct Outcome{std::string records,mask;bool coarse;};
Outcome evaluate(const Input&inp,const B&basis,unsigned long&used,unsigned long cap){I p=inp.p,M=inp.M,H=inp.H;auto a=inp.a,b=inp.b;I A=3*M,hm=H*H,wm=A>hm?A:hm;V lo{0,I(-A*H),0,0,0,0,0},hi{I(wm*wm),I(H*H*H),hm,A,H,I(3*M*M),I(M*M*M)};
std::vector<V>rows;for(auto row:basis)rows.push_back(row);for(int i=0;i<D;i++)for(int j=i+1;j<D;j++)for(int sg:{-1,1}){V v;for(int k=0;k<D;k++)v[k]=rows[i][k]+sg*rows[j][k];rows.push_back(v);}need(rows.size()==49,"full candidate pool");bool coarseclosed=false;std::string mask(H.get_ui()+1,'0');std::ostringstream records;
for(unsigned ri=0;ri<rows.size();ri++){const auto&v=rows[ri];I cc=center(I(v[5]*a[5]+v[6]*b[5]),p),L=cc,R=cc;for(int j=0;j<5;j++)need(mod(I(v[j]-v[5]*a[j]-v[6]*b[j]),p)==0,"dual membership");for(int j=0;j<D;j++){I z=j<5?v[j]:I(-v[j]),x=z*lo[j],y=z*hi[j];L+=(x<y?x:y);R+=(x>y?x:y);}bool coarse=cd(L,p)>fd(R,p);coarseclosed|=coarse;std::string cmask(H.get_ui()+1,'0');I sum=0,max=0;unsigned tighter=0;for(unsigned long ui=0;ui<=H.get_ui();ui++){need(++used<=cap,"work cap");auto cr=curved(v,cc,M,I(ui));I width=cr.second-cr.first;need(width<=R-L,"curved enclosure inside coarse range");sum+=width;if(width>max)max=width;tighter+=width<R-L;if(cd(cr.first,p)>fd(cr.second,p)){cmask[ui]='1';mask[ui]='1';}}if(ri)records<<',';records<<"{\"vector\":";arr(records,v);records<<",\"constant\":\""<<cc<<"\",\"L\":\""<<L<<"\",\"R\":\""<<R<<"\",\"coarse\":"<<(coarse?"true":"false")<<",\"curved_mask\":\""<<cmask<<"\",\"curved_width_sum\":\""<<sum<<"\",\"curved_max_width\":\""<<max<<"\",\"tighter_u\":"<<tighter<<'}';}
return {records.str(),mask,coarseclosed};}

int main(int argc,char**argv){auto start=Clock::now();try{need(argc>=2,"mode");std::string mode=argv[1];if(mode=="controls"){nativecontrols();return 0;}if(mode=="basis-controls"){basiscontrols();return 0;}need(argc==4&&(mode=="cold"||mode=="warm"),"mode input budget");unsigned long cap=std::stoul(argv[3]);need(cap<=33000,"arm cap");std::ifstream in(argv[2]);need(bool(in),"input");std::vector<Input>inputs;Input d;unsigned long declared=0;while(in>>d.id>>d.key>>d.p>>d.M>>d.H){for(auto&x:d.a)in>>x;for(auto&x:d.b)in>>x;need(bool(in)&&d.p>2&&d.M>=0&&d.H>=0&&d.H<=63,"bounded input");declared+=49*(d.H.get_ui()+1);need(declared<=cap&&inputs.size()<20,"preflight");inputs.push_back(d);}need(inputs.size()==20,"all twenty cases");std::map<std::string,Cache>cache;unsigned long used=0;bool comma=false;std::cout<<"{\"rows\":[";for(unsigned ii=0;ii<inputs.size();ii++){const auto&inp=inputs[ii];I p=inp.p,M=inp.M,H=inp.H,A=3*M,hm=H*H,wm=A>hm?A:hm;V lo{0,I(-A*H),0,0,0,0,0},hi{I(wm*wm),I(H*H*H),hm,A,H,I(3*M*M),I(M*M*M)},weights;for(int j=0;j<D;j++){weights[j]=hi[j]-lo[j];if(weights[j]<1)weights[j]=1;}B base=original(p,inp.a,inp.b);bool hit=false,key_rejected=false,fallback=false;std::string fp=fingerprint(inp);auto it=cache.find(inp.key);if(mode=="warm"&&it!=cache.end()){if(it->second.fingerprint==fp&&validbasis(it->second.basis,p,inp.a,inp.b)){base=it->second.basis;hit=true;}else key_rejected=true;}auto reduce=[&](B seed,unsigned&steps){for(auto&row:seed)for(int j=0;j<D;j++)row[j]*=weights[j];bool ok=lll(seed,steps,start);for(auto&row:seed)for(int j=0;j<D;j++){need(row[j]%weights[j]==0,"unscale");row[j]/=weights[j];}need(validbasis(seed,p,inp.a,inp.b),"basis equality");return std::pair<B,bool>{seed,ok};};unsigned steps=0;auto red=reduce(base,steps);B basis=red.first;bool reduced=red.second;Outcome out=evaluate(inp,basis,used,cap);std::string failed="null";
if(hit&&(!reduced||out.mask.find('0')!=std::string::npos)){unsigned long remaining=0;for(unsigned j=ii+1;j<inputs.size();j++)remaining+=49*(inputs[j].H.get_ui()+1);unsigned long extra=49*(H.get_ui()+1);need(used+extra+remaining<=cap,"fallback exceeds reserved work budget");fallback=true;failed="{\"mask\":\""+out.mask+"\",\"lll_complete\":"+(reduced?std::string("true"):std::string("false"))+",\"steps\":"+std::to_string(steps)+",\"candidates\":["+out.records+"]}";unsigned more=0;red=reduce(original(p,inp.a,inp.b),more);steps+=more;basis=red.first;reduced=red.second;out=evaluate(inp,basis,used,cap);}
if(mode=="warm")cache[inp.key]=Cache{fp,basis};if(comma)std::cout<<',';comma=true;bool closed=out.mask.find('0')==std::string::npos;std::cout<<"{\"id\":\""<<inp.id<<"\",\"key\":\""<<inp.key<<"\",\"warm_hit\":"<<(hit?"true":"false")<<",\"key_rejected\":"<<(key_rejected?"true":"false")<<",\"fallback\":"<<(fallback?"true":"false")<<",\"warm_attempt\":"<<failed<<",\"basis_determinant\":\""<<determinant(basis)<<"\",\"coarse_closed\":"<<(out.coarse?"true":"false")<<",\"curved_closed\":"<<(closed?"true":"false")<<",\"curved_mask\":\""<<out.mask<<"\",\"lll_complete\":"<<(reduced?"true":"false")<<",\"steps\":"<<steps<<",\"candidates\":["<<out.records<<"]}";need(std::chrono::duration<double>(Clock::now()-start).count()<78,"native report deadline");}std::cout<<"],\"candidate_u_checks\":"<<used<<"}\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
